local MIN_SIZE = 0.001 -- Roblox's smallest part dimension

local function makePart(row, s: number): BasePart
	local shape = row[1]
	local part: BasePart
	if shape == 'W' then
		part = Instance.new('WedgePart')
	else
		local p = Instance.new('Part')
		if shape == 'C' then
			p.Shape = Enum.PartType.Cylinder
		elseif shape == 'S' then
			p.Shape = Enum.PartType.Ball
		end
		part = p
	end
	local kindName = KINDS[row[3]]
	local kind = M.Materials[kindName]
	part.Name = row[11]
	part.Size = Vector3.new(math.max(row[4] * s, MIN_SIZE), math.max(row[5] * s, MIN_SIZE), math.max(row[6] * s, MIN_SIZE))
	local r = ROTS[row[10]]
	part.CFrame = CFrame.new(row[7] * s, row[8] * s, row[9] * s, r[1], r[2], r[3], r[4], r[5], r[6], r[7], r[8], r[9])
	part.Color = COLORS[row[2]]
	part.Material = kind.Material
	part.Reflectance = kind.Reflectance
	part.Transparency = kind.Transparency
	-- Studs and glowing/see-through parts cast no shadow: cheaper and cleaner on small props.
	part.CastShadow = kind.CastShadow and row[11] ~= 'Stud'
	part.TopSurface = Enum.SurfaceType.Smooth
	part.BottomSurface = Enum.SurfaceType.Smooth
	part.Anchored = true
	part.CanCollide = false
	part.CanTouch = false
	part.CanQuery = false
	return part
end

-- (brief 22) Shoe and box icons come from the game's own part models: Shoe_<ShoeId> (Config/Shoes ids) builds
-- ShoeModels.shoe(<id>, 'R'), Box_<BoxId> builds BoxModels.build(<id>), so Kit.icon3d('Shoe_RedRocket', s) shows the
-- live shoe until its PNG is uploaded (M.Images[id]). They are not in M.Ids (they don't follow the 2x2x2 icon contract).
-- Yaw (degrees) to turn a shoe / box inside build. 0: UIKit's Kit.icon3d already frames Shoe_<id> from Kit.ShoeView
-- (= ShoeModels.View, the PNG's angle), so a turn here would turn it twice. Set it only if a caller frames them with
-- IconModels.View instead.
M.ShoeYaw = 0
M.BoxYaw = 0
local function sibling(name)
	local folder = script and script.Parent
	local mod = folder and folder:FindFirstChild(name)
	if not mod then return nil end
	local ok, result = pcall(require, mod)
	return ok and result or nil
end
-- Turn the parts by `yaw` degrees and give the model a new upright, invisible PrimaryPart `IconRoot` at the old pivot,
-- so a later PivotTo(CFrame.new(pos)) moves it without undoing the turn.
local function turned(m: Model, yaw: number): Model
	local p = m:GetPivot()
	local turn = p * CFrame.Angles(0, math.rad(yaw), 0) * p:Inverse()
	for _, d in m:GetDescendants() do
		if d:IsA('BasePart') then d.CFrame = turn * d.CFrame end
	end
	local root = Instance.new('Part')
	root.Name = 'IconRoot'
	root.Size = Vector3.new(0.2, 0.2, 0.2)
	root.CFrame = CFrame.new(p.Position)
	root.Transparency = 1
	root.CastShadow = false
	root.Anchored = true
	root.CanCollide = false
	root.CanTouch = false
	root.CanQuery = false
	root.Parent = m
	m.PrimaryPart = root
	return m
end
local function external(id: string, s: number): Model?
	local shoe = string.match(id, '^Shoe_(.+)$')
	if shoe then
		local SM = sibling('ShoeModels')
		if SM and SM.Meta and SM.Meta[shoe] then
			local m = SM.shoe(shoe, 'R', s)
			return M.ShoeYaw ~= 0 and turned(m, M.ShoeYaw) or m
		end
		return nil
	end
	local box = string.match(id, '^Box_(.+)$')
	if box then
		local BM = sibling('BoxModels')
		if BM and BM.Meta and BM.Meta[box] then
			local m = BM.build(box, s)
			return M.BoxYaw ~= 0 and turned(m, M.BoxYaw) or m
		end
	end
	return nil
end
function M.isExternal(id: string): boolean
	return string.match(id, '^Shoe_') ~= nil or string.match(id, '^Box_') ~= nil
end

function M.build(id: string, scale: number?): Model
	if M.isExternal(id) then
		local m = external(id, scale or 1)
		assert(m, 'IconModels: unknown id ' .. tostring(id))
		return m
	end
	local rows = DATA[id] or DATA[M.Alias[id] or '']
	assert(rows, 'IconModels: unknown id ' .. tostring(id))
	local s = scale or 1
	local model = Instance.new('Model')
	model.Name = id
	-- Invisible root at the origin: PrimaryPart and pivot (the centre of the icon).
	local root = Instance.new('Part')
	root.Name = 'Root'
	root.Size = Vector3.new(0.2, 0.2, 0.2) * s
	root.CFrame = CFrame.new()
	root.Transparency = 1
	root.CastShadow = false
	root.Anchored = true
	root.CanCollide = false
	root.CanTouch = false
	root.CanQuery = false
	root.Parent = model
	for _, row in rows do
		makePart(row, s).Parent = model
	end
	model.PrimaryPart = root
	model:SetAttribute('ModelId', id)
	model:SetAttribute('Scale', s)
	return model
end

function M.weld(model: Model): Model
	local root = model.PrimaryPart
	assert(root, 'weld: model has no PrimaryPart')
	for _, d in model:GetDescendants() do
		if d:IsA('BasePart') and d ~= root then
			local w = Instance.new('WeldConstraint')
			w.Part0 = root
			w.Part1 = d
			w.Parent = d
			d.Anchored = false
			d.Massless = true
		end
	end
	root.Anchored = false
	return model
end

M.View = Vector3.new(-0.2883, 0.3243, -0.9009) -- direction from the model toward the camera in the Blender renders

function M.viewport(id: string, size: UDim2?): ViewportFrame
	local meta = M.Meta[id]
	assert(meta, 'IconModels: unknown id ' .. tostring(id))
	local vf = Instance.new('ViewportFrame')
	vf.Name = id
	vf.Size = size or UDim2.fromScale(1, 1)
	vf.BackgroundTransparency = 1
	vf.Ambient = Color3.fromRGB(170, 170, 180)
	vf.LightColor = Color3.fromRGB(255, 248, 235)
	vf.LightDirection = Vector3.new(0.6, -1, 0.5)
	local model = M.build(id, 1)
	model.Parent = vf
	local cam = Instance.new('Camera')
	cam.FieldOfView = 30
	local radius = meta.Size.Magnitude / 2
	local dist = radius / math.tan(math.rad(cam.FieldOfView / 2)) * 1.05
	cam.CFrame = CFrame.lookAt(meta.Center + M.View.Unit * dist, meta.Center)
	cam.Parent = vf
	vf.CurrentCamera = cam
	return vf
end

return M
